#include "ShaderHunter.h"
#include "MarkedGroundFogRemoval.h"
#include <MinHook.h>
#include <d3d11_4.h>
#include <d3dcompiler.h>
#include <wrl/client.h>
#include <cstdio>
#include <fstream>
#include <vector>
using Microsoft::WRL::ComPtr;
static unsigned checks{};
static void Require(bool ok,const char* text){++checks;if(!ok){fprintf(stderr,"FAIL: %s\n",text);fflush(stderr);ExitProcess(1);}}
static uint64_t Counter(const char* name){auto status=hunter::StatusJSON();auto key=std::string("\"")+name+"\":";auto p=status.find(key);Require(p!=status.npos,name);return std::stoull(status.substr(p+key.size()));}
static ComPtr<ID3DBlob> Compile(const char* source,const char* profile){ComPtr<ID3DBlob> code,error;auto hr=D3DCompile(source,strlen(source),nullptr,nullptr,nullptr,"main",profile,0,0,&code,&error);if(FAILED(hr)&&error)fprintf(stderr,"%s\n",(char*)error->GetBufferPointer());Require(SUCCEEDED(hr),profile);return code;}
static std::vector<char> Fixture(const wchar_t* path,uint64_t expected){std::ifstream f(path,std::ios::binary);std::vector<char> code{std::istreambuf_iterator<char>(f),{}};uint64_t hash=14695981039346656037ull;for(auto byte:code){hash^=(uint8_t)byte;hash*=1099511628211ull;}Require(!code.empty()&&hash==expected,"exact private captured bytecode");return code;}
// Pixel-output tests use executable synthetic shaders with the production
// identities attached explicitly. Separate zero-vertex calls below establish
// that the REAL captured shaders receive those identities through creation hooks.
static void Tag(ID3D11DeviceChild* shader,uint64_t hash,unsigned stage,bool bytecode=true){const GUID tag={0x2b59db30,0x7880,0x4c13,{0xaf,0x66,0x13,0xd4,0x9e,0x74,0x40,0x11}};struct ID{uint64_t hash;uint32_t stage,bytecode;}id{hash,stage,bytecode?1u:0u};Require(SUCCEEDED(shader->SetPrivateData(tag,sizeof(id),&id)),"synthetic identity proxy");}
int wmain(int argc,wchar_t** argv){
 Require(argc==4||argc==5,"output directory, private VS DXBC, private PS DXBC, optional --unprotected");bool protect=argc==4;Require(protect||wcscmp(argv[4],L"--unprotected")==0,"context mode");
 auto root=std::filesystem::absolute(argv[1]);std::filesystem::create_directories(root);auto ini=root.parent_path()/L"AvalonVR.ini";
 auto Configure=[&](const wchar_t* value){Require(WritePrivateProfileStringW(L"Effects",L"DisableGroundFog",value,ini.c_str())!=0,"write reversible ground-fog option");};
 Configure(L"1");Require(WritePrivateProfileStringW(L"Effects",L"DisableMarkedFogLens",L"0",ini.c_str())!=0,"other effect removal independent");Require(WritePrivateProfileStringW(L"Debug",L"ShadowConsumerDiagnostics",L"0",ini.c_str())!=0,"diagnostics off");
 auto capturedVS=Fixture(argv[2],MarkedGroundFogRemoval::VertexShader),capturedPS=Fixture(argv[3],MarkedGroundFogRemoval::PixelShader);
 ComPtr<ID3D11Device> device;ComPtr<ID3D11DeviceContext> context;D3D_FEATURE_LEVEL level{};Require(SUCCEEDED(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&device,&level,&context)),"hardware D3D11");ComPtr<ID3D11Multithread> multithread;Require(SUCCEEDED(context.As(&multithread)),"context protection");multithread->SetMultithreadProtected(protect);
 Require(MH_Initialize()==MH_OK,"MinHook");Require(hunter::Install(device.Get(),context.Get(),root),"production hooks");context->Dispatch(0,0,0);
 ComPtr<ID3D11VertexShader> realVS;ComPtr<ID3D11PixelShader> realPS;Require(SUCCEEDED(device->CreateVertexShader(capturedVS.data(),capturedVS.size(),nullptr,&realVS)),"real marked VS registration");Require(SUCCEEDED(device->CreatePixelShader(capturedPS.data(),capturedPS.size(),nullptr,&realPS)),"real marked PS registration");context->VSSetShader(realVS.Get(),nullptr,0);context->PSSetShader(realPS.Get(),nullptr,0);auto before=Counter("groundFogDraws");context->Draw(0,0);Require(Counter("groundFogDraws")==before+1,"real marked pair suppressed once");Require(Counter("groundFogPixelMatches")==1&&Counter("groundFogVertexMatches")==1,"both real identities recognized");
 auto vertex=Compile("float4 main(uint id:SV_VertexID):SV_Position{float2 uv=float2((id<<1)&2,id&2);return float4(uv*float2(2,-2)+float2(-1,1),0,1);}","vs_5_0");auto proxyVertex=Compile("float4 main(uint id:SV_VertexID):SV_Position{float2 uv=float2((id<<1)&2,id&2);return float4(uv*float2(2,-2)+float2(-1,1),0.125,1);}","vs_5_0");auto pixel=Compile("float4 main():SV_Target{return float4(1,0,0,1);}","ps_5_0");auto proxyPixel=Compile("[earlydepthstencil]float4 main():SV_Target{return float4(1,0,0,1);}","ps_5_0");ComPtr<ID3D11VertexShader> normalVS,markedVS;ComPtr<ID3D11PixelShader> normalPS,markedPS;Require(SUCCEEDED(device->CreateVertexShader(vertex->GetBufferPointer(),vertex->GetBufferSize(),nullptr,&normalVS)),"unrelated VS");Require(SUCCEEDED(device->CreateVertexShader(proxyVertex->GetBufferPointer(),proxyVertex->GetBufferSize(),nullptr,&markedVS)),"synthetic VS proxy");Require(SUCCEEDED(device->CreatePixelShader(pixel->GetBufferPointer(),pixel->GetBufferSize(),nullptr,&normalPS)),"unrelated PS");Require(SUCCEEDED(device->CreatePixelShader(proxyPixel->GetBufferPointer(),proxyPixel->GetBufferSize(),nullptr,&markedPS)),"synthetic PS proxy");Tag(markedVS.Get(),MarkedGroundFogRemoval::VertexShader,1);Tag(markedPS.Get(),MarkedGroundFogRemoval::PixelShader,0);
 D3D11_TEXTURE2D_DESC td{};td.Width=td.Height=4;td.MipLevels=td.ArraySize=td.SampleDesc.Count=1;td.Format=DXGI_FORMAT_R8G8B8A8_UNORM;td.BindFlags=D3D11_BIND_RENDER_TARGET|D3D11_BIND_UNORDERED_ACCESS;ComPtr<ID3D11Texture2D> target,read;Require(SUCCEEDED(device->CreateTexture2D(&td,nullptr,&target)),"target");ComPtr<ID3D11RenderTargetView> rtv;ComPtr<ID3D11UnorderedAccessView> uav;Require(SUCCEEDED(device->CreateRenderTargetView(target.Get(),nullptr,&rtv)),"RTV");Require(SUCCEEDED(device->CreateUnorderedAccessView(target.Get(),nullptr,&uav)),"UAV");td.Usage=D3D11_USAGE_STAGING;td.BindFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;Require(SUCCEEDED(device->CreateTexture2D(&td,nullptr,&read)),"test-only readback");
 auto Bind=[&](ID3D11DeviceContext* c,ID3D11VertexShader* vs,ID3D11PixelShader* ps){auto rt=rtv.Get();c->OMSetRenderTargets(1,&rt,nullptr);D3D11_VIEWPORT vp{0,0,4,4,0,1};c->RSSetViewports(1,&vp);c->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);c->VSSetShader(vs,nullptr,0);c->PSSetShader(ps,nullptr,0);};
 auto Pixel=[&](){context->CopyResource(read.Get(),target.Get());D3D11_MAPPED_SUBRESOURCE m{};Require(SUCCEEDED(context->Map(read.Get(),0,D3D11_MAP_READ,0,&m)),"test-only GPU completion");auto value=*(const uint32_t*)m.pData;context->Unmap(read.Get(),0);return value;};float black[4]{};
 Bind(context.Get(),normalVS.Get(),normalPS.Get());context->ClearRenderTargetView(rtv.Get(),black);context->Draw(3,0);Require(Pixel()==0xff0000ff,"unrelated graphics renders normally while removal ON");
 for(auto vsOnly:{false,true}){Bind(context.Get(),vsOnly?markedVS.Get():normalVS.Get(),vsOnly?normalPS.Get():markedPS.Get());context->ClearRenderTargetView(rtv.Get(),black);before=Counter("groundFogDraws");context->Draw(3,0);Require(Pixel()==0&&Counter("groundFogDraws")==before+1,vsOnly?"VS-only mark removes draw":"PS-only mark removes draw");}
 Bind(context.Get(),markedVS.Get(),markedPS.Get());before=Counter("groundFogDraws");context->Draw(3,0);Require(Pixel()==0&&Counter("groundFogDraws")==before+1,"both marks remove one command, preserving target");
 ComPtr<ID3D11VertexShader> boundVS;ComPtr<ID3D11PixelShader> boundPS;ComPtr<ID3D11RenderTargetView> boundRT;context->VSGetShader(&boundVS,nullptr,nullptr);context->PSGetShader(&boundPS,nullptr,nullptr);context->OMGetRenderTargets(1,&boundRT,nullptr);Require(boundVS==markedVS&&boundPS==markedPS&&boundRT==rtv,"bindings unchanged");
 D3D11_BUFFER_DESC ad{};ad.ByteWidth=32;ad.MiscFlags=D3D11_RESOURCE_MISC_DRAWINDIRECT_ARGS;UINT arguments[8]={3,1,0,0,0,0,0,0};D3D11_SUBRESOURCE_DATA init{arguments,0,0};ComPtr<ID3D11Buffer> args;Require(SUCCEEDED(device->CreateBuffer(&ad,&init,&args)),"indirect args");before=Counter("groundFogDraws");context->Draw(3,0);context->DrawIndexed(3,0,0);context->DrawInstanced(3,1,0,0);context->DrawIndexedInstanced(3,1,0,0,0);context->DrawAuto();context->DrawIndexedInstancedIndirect(args.Get(),0);context->DrawInstancedIndirect(args.Get(),0);Require(Counter("groundFogDraws")==before+7&&Pixel()==0,"all seven graphics command forms suppressed");
 {hunter::Bypass ownTransfer;context->Draw(3,0);}Require(Pixel()==0xff0000ff,"mod-owned transfer bypass");hunter::Control(VK_HOME);Require(hunter::StatusJSON().find("\"groundFogRemoval\":true")!=std::string::npos,"Home preserves configured removal");
 ComPtr<ID3D11DeviceContext> deferred;Require(SUCCEEDED(device->CreateDeferredContext(0,&deferred)),"future deferred context");Bind(deferred.Get(),markedVS.Get(),markedPS.Get());context->ClearRenderTargetView(rtv.Get(),black);deferred->Draw(3,0);ComPtr<ID3D11CommandList> list;Require(SUCCEEDED(deferred->FinishCommandList(FALSE,&list)),"deferred list");context->ExecuteCommandList(list.Get(),TRUE);Require(Pixel()==0,"deferred draw removal");
 Tag(markedPS.Get(),MarkedGroundFogRemoval::PixelShader,0,false);Bind(context.Get(),normalVS.Get(),markedPS.Get());context->Draw(3,0);Require(Pixel()==0xff0000ff,"object token never suppresses");Tag(markedPS.Get(),MarkedGroundFogRemoval::VertexShader,0);context->Draw(3,0);Require(Pixel()==0xff0000ff,"wrong stage never suppresses");Tag(markedPS.Get(),MarkedGroundFogRemoval::PixelShader,0);
 auto compute=Compile("RWTexture2D<float4> result:register(u0);[numthreads(1,1,1)]void main(uint3 p:SV_DispatchThreadID){result[p.xy]=float4(0,1,0,1);}","cs_5_0");ComPtr<ID3D11ComputeShader> cs;Require(SUCCEEDED(device->CreateComputeShader(compute->GetBufferPointer(),compute->GetBufferSize(),nullptr,&cs)),"unrelated compute");context->OMSetRenderTargets(0,nullptr,nullptr);auto u=uav.Get();context->CSSetUnorderedAccessViews(0,1,&u,nullptr);context->CSSetShader(cs.Get(),nullptr,0);context->Dispatch(4,4,1);Require(Pixel()==0xff00ff00,"compute untouched by ground removal");u=nullptr;context->CSSetUnorderedAccessViews(0,1,&u,nullptr);
 Configure(L"0");Sleep(1100);hunter::Tick(true);Require(hunter::StatusJSON().find("\"groundFogRemoval\":false")!=std::string::npos,"live INI OFF");Bind(context.Get(),markedVS.Get(),markedPS.Get());context->ClearRenderTargetView(rtv.Get(),black);context->Draw(3,0);Require(Pixel()==0xff0000ff,"OFF restores graphics output");
 Configure(L"1");Sleep(1100);hunter::Tick(true);context->ClearRenderTargetView(rtv.Get(),black);context->Draw(3,0);Require(Pixel()==0,"live INI ON removes output again");Require(hunter::StatusJSON().find("\"markedEffectRemoval\":false")!=std::string::npos,"fog/lens option remains independent");Require(SUCCEEDED(device->GetDeviceRemovedReason()),"device healthy");
 MH_DisableHook(MH_ALL_HOOKS);MH_Uninitialize();printf("PASS: %u ground-fog GPU checks (%s), real private identity registration and synthetic output tests.\n",checks,protect?"protected":"unprotected");fflush(stdout);ExitProcess(0);
}
